import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 3

def design(feats):
    # Find features with significant association (p < 0.05 or |t| > 2)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        # Skip constant features
        if np.std(feats.x[:, i]) > 1e-6:  
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            if abs(t_stat) > 2 or p_val < 0.05:
                sig_features.append((fid, t_stat, p_val))

    # Sort by effect size (absolute t-statistic)
    sig_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # If no significant features, return empty design
    if len(sig_features) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check for interaction terms among top features
    top_features = [f[0] for f in sig_features[:10]]

    # Look for correlated pairs that might suggest interaction
    candidates = []
    for i, fid1 in enumerate(top_features):
        for j, fid2 in enumerate(top_features[i+1:], i+1):
            col1_idx = feats.column(fid1)
            col2_idx = feats.column(fid2)
            corr = np.corrcoef(feats.x[:, col1_idx], feats.x[:, col2_idx])[0, 1]
            if abs(corr) >= 0.6:
                candidates.append((fid1, fid2, corr))

    # Try to find best interaction
    best_score = -np.inf
    best_pair = None

    for fid1, fid2, corr in candidates:
        col1_idx = feats.column(fid1)
        col2_idx = feats.column(fid2)

        # Create interaction term
        interaction = feats.x[:, col1_idx] * feats.x[:, col2_idx]

        # Fit logistic regression with interaction
        X = np.column_stack([feats.x[:, col1_idx], feats.x[:, col2_idx], interaction])
        lr = LogisticRegression(fit_intercept=True, max_iter=1000)
        lr.fit(X, feats.y)

        # Score based on likelihood improvement
        score = lr.score(X, feats.y)
        if score > best_score:
            best_score = score
            best_pair = (fid1, fid2)

    # Return best interaction if found
    if best_pair:
        return Design(
            drivers=(best_pair[0], best_pair[1]),
            columns=(best_pair[0], best_pair[1]),
            products=(best_pair,),
            loadings={}
        )

    # Otherwise return top single feature
    if sig_features:
        top_fid = sig_features[0][0]
        return Design(
            drivers=(top_fid,),
            columns=(top_fid,),
            products=(),
            loadings={top_fid: 1.0}
        )

    return Design(drivers=(), columns=(), products=(), loadings={})

